components.css:
.project-card{display:block;font-family:"Geist Variable",ui-sans-serif,system-ui,sans-serif;color:var(--color-heading,#0a0a0a);text-decoration:none;max-width:212px}.ds-preview{aspect-ratio:5/4;overflow:hidden;border-radius:10px;background:rgba(0,0,0,.035)}.ds-caption{display:flex;align-items:baseline;justify-content:space-between;gap:8px;margin-top:8px}.ds-caption h2{font-size:15px;font-weight:500;line-height:1.6;margin:0}.ds-caption span{font-size:12px;color:var(--color-subtle,#74747a);font-variant-numeric:tabular-nums}.project-card p{font-size:13px;line-height:1.625;color:var(--color-muted,#6e6e73);margin:4px 0 0}.project-card:focus-visible{outline:2px solid var(--color-muted,#6e6e73);outline-offset:5px;border-radius:2px}/* SVG previews use the same neutral palette as the surrounding portfolio. */
.project-art {
  display: block;
  width: 100%;
  height: 100%;
}
.preview-window,
.preview-shadow {
  filter: drop-shadow(0 5px 5px rgb(26 26 30 / 5%));
}

.finance-card,
.finance-receipt,
.finance-coin,
.diary-pen,
.anton-caption,
.bloom-book,
.clayo-call,
.clayo-meter,
.snorlax-file,
.snorlax-back-folder,
.snorlax-upload {
  transition: transform 600ms cubic-bezier(0.22, 1, 0.36, 1);
  transform-box: fill-box;
  transform-origin: center;
}
.bloom-book-left {
  transform: rotate(-9deg);
}
.bloom-book-right {
  transform: rotate(9deg);
}
.bloom-book {
  filter: drop-shadow(0 4px 3px rgb(26 26 30 / 6%));
}
.bloom-progress {
  stroke-dasharray: 100;
  stroke-dashoffset: 72;
  transition: stroke-dashoffset 1200ms cubic-bezier(0.22, 1, 0.36, 1);
}
.clayo-waves {
  opacity: 0.35;
  transition: opacity 300ms;
}
.snorlax-file-two {
  transition-delay: 35ms;
}
.snorlax-file-three {
  transition-delay: 70ms;
}
.snorlax-file-four {
  transition-delay: 105ms;
}

.project-card:is(:hover, :focus-visible) .anton-caption {
  transform: translateY(-4px);
}
.project-card:is(:hover, :focus-visible) .anton-playhead {
  animation: preview-scrub 2200ms ease-in-out infinite alternate;
}
.project-card:is(:hover, :focus-visible) .bloom-book-left {
  transform: translate(-9px, -4px) rotate(-15deg);
}
.project-card:is(:hover, :focus-visible) .bloom-book-right {
  transform: translate(9px, -4px) rotate(15deg);
}
.project-card:is(:hover, :focus-visible) .bloom-book-center {
  transform: translateY(-9px);
}
.project-card:is(:hover, :focus-visible) .bloom-progress {
  stroke-dashoffset: 18;
}
.project-card:is(:hover, :focus-visible) .clayo-call {
  transform: translate(-5px, -7px);
}
.project-card:is(:hover, :focus-visible) .clayo-meter {
  transform: scaleX(1.35);
  transform-origin: left;
}
.project-card:is(:hover, :focus-visible) .clayo-waves {
  animation: preview-ring 1400ms ease-in-out infinite;
}
.project-card:is(:hover, :focus-visible) .snorlax-back-folder {
  transform: translateY(-6px);
}
.project-card:is(:hover, :focus-visible) .snorlax-file {
  transform: translateY(-4px);
}
.project-card:is(:hover, :focus-visible) .snorlax-upload {
  transform: translateY(-7px);
}

@keyframes preview-scrub {
  from {
    transform: translateX(-24px);
  }
  to {
    transform: translateX(116px);
  }
}
@keyframes preview-ring {
  0%,
  100% {
    opacity: 0.3;
  }
  50% {
    opacity: 1;
  }
}

@media (prefers-reduced-motion: reduce) {
  .project-art,
  .project-art * {
    animation: none !important;
    transition: none !important;
  }
}

.finance-coin {
  transition-delay: 40ms;
}
.diary-writing {
  stroke-dasharray: 100;
  stroke-dashoffset: 62;
  transition: stroke-dashoffset 800ms cubic-bezier(0.22, 1, 0.36, 1);
}
.project-card:is(:hover, :focus-visible) .finance-receipt {
  transform: translateY(-9px);
}
.project-card:is(:hover, :focus-visible) .finance-coin {
  transform: translate(-3px, -4px);
}
.project-card:is(:hover, :focus-visible) .diary-pen {
  transform: translate(7px, -5px);
}
.project-card:is(:hover, :focus-visible) .diary-writing {
  stroke-dashoffset: 0;
}

.project-card:is(:hover, :focus-visible) .finance-card {
  transform: translate(-4px, -5px);
}
